import { getPlanLimits } from \"@/config/plan-limits\";
import { emit } from \"@/lib/event-bus\";
import { newId } from \"@/lib/id\";
import * as invoiceRepo from \"@/server/repositories/invoice-repository\";
import * as orgRepo from \"@/server/repositories/organization-repository\";
import { toIsoTimestamp } from \"@/types/common\";
import { record } from \"./activity-service\";
import { notify } from \"./notification-service\";
import type { BillingInterval, PlanId, Subscription } from \"@/types/billing\";
import type { IsoTimestamp, OrgId, UserId } from \"@/types/common\";

const DAY = 86_400_000;
export function periodEnd(start: Date, interval: BillingInterval): Date {
  const result = new Date(start);
  const day = result.getUTCDate();
  result.setUTCDate(1);
  result.setUTCMonth(result.getUTCMonth() + (interval === \"annual\" ? 12 : 1));
  const last = new Date(Date.UTC(result.getUTCFullYear(), result.getUTCMonth() + 1, 0)).getUTCDate();
  result.setUTCDate(Math.min(day, last));
  return result;
}
export function fullCharge(plan: PlanId, seats: number, interval: BillingInterval): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * (interval === \"annual\" ? 12 : 1);
}
export function prorate(amount: number, subscription: Subscription, now: Date): number {
  const days = Math.max(1, Math.round((Date.parse(subscription.currentPeriodEnd) - Date.parse(subscription.currentPeriodStart)) / DAY));
  const left = Math.max(0, Math.ceil((Date.parse(subscription.currentPeriodEnd) - now.getTime()) / DAY));
  return Math.floor(amount * Math.min(left, days) / days);
}
export async function issueInvoice(orgId: OrgId, amountCents: number, start: IsoTimestamp, end: IsoTimestamp, now: Date, actorId: UserId | null = null): Promise<void> {
  if (amountCents <= 0) return;
  const invoice = await invoiceRepo.insertInvoice(orgId, { orgId, number: "'`INV-${newId()}`, amountCents, currency: "usd", periodStart: start, periodEnd: end, paidAt: null });
  const occurredAt = toIsoTimestamp(now);
  await record(orgId, "billing.invoice_issued", { actorId, subjectKind: "subscription", subjectId: orgId, summary: `Invoice ${invoice.number} issued`, metadata: { invoiceId: invoice.id, amountCents } });
  const org = await orgRepo.findOrgById(orgId);
  if (org) await notify(orgId, "invoice_issued", [org.ownerId], { title: "Invoice issued", body: `Invoice ${invoice.number} was issued`, href: "/settings/billing/invoices", actorId: null });
  await emit("billing.invoice_issued", { orgId, actorId, occurredAt, invoiceId: invoice.id, invoiceNumber: invoice.number, amountCents, periodStart: start, periodEnd: end });
}
